// Campaign fixtures (CP-C3): scripted, demo-style waves for the seven nights, so the hosted demo works in mock mode.
// Contract: contract/V1_1.md sections 3, 4, 6, 7, 11 and 12. Generated by tools/make-fixtures.ts into contract/fixtures.
//
// Names: `night1` to `night6` and `finale` (night 7) are the starting crew (no gear). `<name>-<letters>` carries the gear
// (R retry, J journal, I idempotency, B breaker, Q offline queue), e.g. `night1-j-i`, `night2-r-b`. Committed files exist
// for no gear and for the night's gear hint; `campaignFixture` builds any other combination on demand for the mock.
// `<name>-none` and `<name>-nogear` are accepted aliases of the no-gear fixture.
//
// Lane 1 is "Your Crew" (tier `crew`, lane_ready parts = the gear), lanes 2 to 5 are the rivals. The night's plan presses
// land on lane 1 only; boss windows hit all lanes. Nights 4, 5 and the finale rely on play-test v2 mechanics (world faults,
// boss recovery scoring, decisions). They are built here from the V1_1 types (sim decorator and scripted lanes) until S1
// ships the engine side, which is why they stay Partial in tasks.md.
import { APPS, TIERS, TIMING, type HauntEvent, type PartId, type TierId } from '@haunt/shared';
import { loadCampaign } from '../../haunt/src/campaign/nights';
import type { CampaignNight } from '../../haunt/src/campaign/types';
import type { ArmSpec } from '../src/sim/plan';
import { assembleWave, assignSeq, BASE_TS, planWave, type BossSpec, type WaveSpec } from '../src/sim/wave';
import { decorateV11 } from '../src/sim/v11';
import { DUR, Script, withScripts } from '../src/sim/fixtures-v11';

/** Slow pace factor of V1_1 section 1. */
const PACE = 3;
/** The scripted lane durations are written for the show pace (2); slow is 1.5 times that. */
const SCALE = PACE / 2;
const CREW_LABEL = 'Your Crew';

/** Canonical gear order and letters (same as `gear.json` badges). */
export const GEAR_ORDER: PartId[] = ['retry', 'journal', 'idempotency', 'breaker', 'offline_queue'];
const LETTER: Record<PartId, string> = { retry: 'r', journal: 'j', idempotency: 'i', breaker: 'b', offline_queue: 'q' };

export const canonicalParts = (parts: readonly PartId[]): PartId[] => GEAR_ORDER.filter((p) => parts.includes(p));
export const nightFixtureBase = (night: number): string => (night === 7 ? 'finale' : `night${night}`);
export const nightFixtureName = (night: number, parts: readonly PartId[] = []): string => {
  const ps = canonicalParts(parts);
  return ps.length ? `${nightFixtureBase(night)}-${ps.map((p) => LETTER[p]).join('-')}` : nightFixtureBase(night);
};

/** Parses a fixture name (`night2-r-b`, `finale`, `night3-none`) back to a night and parts. */
export function parseCampaignFixtureName(name: string): { night: number; parts: PartId[] } | undefined {
  const m = /^(night([1-6])|finale)((?:-[rjibq])*|-none|-nogear)$/.exec(name);
  if (!m) return undefined;
  const night = m[1] === 'finale' ? 7 : Number(m[2]);
  const rest = m[3];
  if (!rest || rest === '-none' || rest === '-nogear') return { night, parts: [] };
  const letters = rest.slice(1).split('-');
  const parts = letters.map((l) => GEAR_ORDER.find((p) => LETTER[p] === l)!);
  if (new Set(parts).size !== parts.length) return undefined;
  const canon = canonicalParts(parts);
  return canon.every((p, i) => p === parts[i]) ? { night, parts } : undefined;
}

// ------------------------------------------------------------------------------------------------ plan to arms

/** World faults that the lane planner cannot express yet map to a planner fault and are renamed afterwards (by creature). */
const PLANNER_FAULT: Record<string, string> = {};

/** Longest pause between two presses of one stage in the mock (the planner's handoff stall is about two seconds). */
const AFTER_PREV_CAP_MS = 800;

const orderNo = (id?: string): number => { const m = /(\d+)$/.exec(id ?? ''); return m ? Number(m[1]) : 1; };

interface Arms { arms: ArmSpec[]; bosses: BossSpec[]; renames: Map<string, string> }

/** The night plan as planner arms for lane 1 and boss windows. Boss `startAtMs` is the start; the warning leads it by bossWarnMs. */
function plannerArms(night: CampaignNight): Arms {
  const arms: ArmSpec[] = [];
  const bosses: BossSpec[] = [];
  const renames = new Map<string, string>();
  let prev: NonNullable<ArmSpec['when']> | undefined;
  night.plan.forEach((e, idx) => {
    if ('boss' in e) { bosses.push({ fault: e.boss, warnAt: Math.max(0, e.startAtMs - TIMING.bossWarnMs) }); return; }
    const fault = PLANNER_FAULT[e.fault] ?? e.fault;
    if (fault !== e.fault) renames.set(e.creature, e.fault);
    const base = (id: string): ArmSpec => ({
      id, fault, creature: e.creature, source: 'demo', ...(e.point ? { point: e.point } : {}), ...(e.scope ? { scope: e.scope } : {}),
    });
    if (e.when?.stage) {
      const orders = e.forEachOrder ? Array.from({ length: night.orders }, (_, k) => k + 1) : [orderNo(e.when.order)];
      for (const o of orders) {
        const when = { order: o, stage: e.when.stage, attempt: e.when.attempt ?? 1, delay: e.delayMs ?? 0 };
        arms.push({ ...base(`n${night.id}-${idx}-${o}`), when });
        prev = when;
      }
    } else if (e.afterPrevMs !== undefined && prev) {
      // The planner's world faults are short, so the pause is capped to land while the first fault is still in effect.
      const when = { ...prev, delay: prev.delay + Math.min(e.afterPrevMs, AFTER_PREV_CAP_MS) };
      arms.push({ ...base(`n${night.id}-${idx}`), when });
      prev = when;
    } else if (e.atMs !== undefined) {
      arms.push({ ...base(`n${night.id}-${idx}`), at: e.atMs });
    }
  });
  return { arms, bosses, renames };
}

// ------------------------------------------------------------------------------------------------ shared pieces

const tiersOf = (night: CampaignNight): TierId[] => ['rookie', ...night.rivals];

function laneReady(night: CampaignNight, parts: readonly PartId[]): { tier: string; label: string; parts: string[] }[] {
  return tiersOf(night).map((t, i) => (i === 0 ? { tier: 'crew', label: CREW_LABEL, parts: [...parts] } : { tier: t, label: TIERS[t].label, parts: [...TIERS[t].parts] }));
}

function waveSpec(night: CampaignNight, parts: readonly PartId[]): WaveSpec {
  return { app: night.app ?? 'orders', tiers: tiersOf(night), orders: night.orders, seed: night.seed, pace: PACE, laneParts: [[...parts]], laneReady: laneReady(night, parts) };
}

/** `wave_start.detail.campaign` (V1_1 section 12). */
function tagCampaign(events: HauntEvent[], night: number, parts: readonly PartId[]): void {
  const ws = events.find((e) => e.type === 'wave_start');
  if (ws) ws.detail = { ...ws.detail, campaign: { night, parts: [...parts] } };
}

const finish = (events: HauntEvent[], night: number, parts: readonly PartId[]): HauntEvent[] => {
  tagCampaign(events, night, parts);
  return assignSeq(decorateV11(events, { pace: PACE }));
};

// ------------------------------------------------------------------------------------------------ nights 1 to 6

/** Pause between one boss window ending and the next warning (the sim shifts lanes by up to a few seconds of travel). */
const BOSS_GAP_MS = 3_000;
/** A later boss needs at least this much wave left after its start. */
const BOSS_TAIL_MS = 25_000;

/**
 * The mock plays one boss window at a time: at the slow pace a window lasts longer than the plan's 20 s spacing, so each
 * later boss is moved to start after the previous window ended (never earlier than the plan says). A boss that would open
 * too close to the end of the wave is left out, so the mock plays two of night 5's three bosses (Partial in tasks.md).
 */
function sequenceBosses(spec: WaveSpec, arms: ArmSpec[], bosses: BossSpec[]): { pw: ReturnType<typeof planWave>; bosses: BossSpec[] } {
  const placed: BossSpec[] = [];
  let pw = planWave(spec, { 1: arms }, placed);
  for (const b of bosses) {
    const prev = pw.bosses[pw.bosses.length - 1];
    const warnAt = prev ? Math.max(b.warnAt, prev.endAt + BOSS_GAP_MS) : b.warnAt;
    // A window that would open when the lanes are about to finish has nobody to hit: leave it out.
    const lanesEnd = Math.min(...pw.plans.map((p) => p.endT));
    if (prev && warnAt + TIMING.bossWarnMs > lanesEnd - BOSS_TAIL_MS) break;
    placed.push({ ...b, warnAt });
    pw = planWave(spec, { 1: arms }, placed);
  }
  return { pw, bosses: placed };
}

function plannedNight(night: CampaignNight, parts: readonly PartId[]): HauntEvent[] {
  const { arms, bosses, renames } = plannerArms(night);
  const events = assembleWave(sequenceBosses(waveSpec(night, parts), arms, bosses).pw, BASE_TS);
  for (const e of events) {
    const to = e.type === 'chaos' && e.lane === 1 ? renames.get(e.detail!.creature as string) : undefined;
    if (to) e.detail = { ...e.detail, fault: to };
  }
  return finish(events, night.id, parts);
}

// ------------------------------------------------------------------------------------------------ finale

/** The stages of a clean order at the slow pace, from `from` up to and including `to`. */
function runSlow(s: Script, order: string, from = 'account', to = 'handoff', suffix?: string): void {
  const ids = APPS.orders.stages.map((d) => d.id);
  for (let i = ids.indexOf(from); i <= ids.indexOf(to); i++) s.stage(order, ids[i], { ms: Math.round(DUR[ids[i]] * SCALE), suffix });
}

/**
 * Night 7: lane 1 is scripted so it can carry the wrong-order decision (V1_1 section 7) and the storm. The typo hits order 2
 * (detected at confirmation, the Crew picks a discount). The storm lands on the stage lane 1 is in at the boss start, or on the first stage of the next plain order:
 * a Crew with retry rides it out (`boss recovered`), without retry the order is cancelled.
 */
function finaleNight(night: CampaignNight, parts: readonly PartId[]): HauntEvent[] {
  const boss = night.plan.find((e) => 'boss' in e) as Extract<CampaignNight['plan'][number], { boss: string }>;
  const warnAt = Math.max(0, boss.startAtMs - TIMING.bossWarnMs);
  const startAt = warnAt + TIMING.bossWarnMs;
  const base = assembleWave(planWave(waveSpec(night, parts), {}, [{ fault: boss.boss, warnAt }]), BASE_TS).filter((e) => e.lane !== 1);

  const s = new Script(1, 'rookie', night.orders);
  const ids = APPS.orders.stages.map((d) => d.id);
  const rides = parts.includes('retry');
  let hit = false;
  const stormChaos = { creature: 'headless_horseman', fault: boss.boss };

  const cleanOrder = (i: number, canBeHit: boolean): void => {
    const o = s.start(i);
    let survived = false;
    for (const id of ids) {
      const ms = Math.round(DUR[id] * SCALE);
      const t0 = s.t;
      if (canBeHit && !hit && t0 + ms > startAt) {
        hit = true;
        const afterMs = Math.max(150, startAt - t0);
        if (!rides) { s.cancel(o, id, { error: 'storm: the road is gone', afterMs, chaos: stormChaos }); return; }
        s.stage(o, id, { ms, fails: [{ error: 'storm: signal lost', afterMs, action: 'backoff', recoverMs: 6000, chaos: stormChaos }] });
        survived = true;
      } else s.stage(o, id, { ms });
    }
    s.at(s.t, 'order_done', { clean: !survived, ms: 0, repeats: 0 }, o);
    s.counts.completed++;
    if (survived) { s.sc(60, 'order with repeats'); s.sc(100, 'boss survived'); } else s.sc(100, 'order clean');
  };

  const typoOrder = (i: number): void => {
    const o = s.start(i);
    s.at(s.t + 300, 'chaos', { creature: 'prankster', fault: 'order_typo', scope: 'outer', depth: 1, injectedAt: 'during', source: 'demo' });
    runSlow(s, o, 'account', 'payment');
    const t0 = s.t;
    s.at(t0, 'stage_start', { attempt: 1 }, o, 'confirmation');
    const failT = t0 + Math.round(700 * SCALE);
    s.at(failT, 'stage_fail', { error: 'wrong_order', retryable: false, attempt: 1 }, o, 'confirmation');
    s.at(failT, 'decision_needed', { order: o, kind: 'wrong_order', detectedAt: 'confirmation', options: ['refund', 'discount', 'redo'], defaultChoice: 'discount', timeoutMs: 12000 }, o);
    const madeT = failT + 4200;
    s.at(madeT, 'decision_made', { order: o, choice: 'discount', source: 'user' }, o);
    s.t = madeT;
    s.at(s.t + 150, 'effect', { kind: 'discount', key: `${o}:discount`, replayed: false, amount: 600 }, o);
    s.t += 300;
    s.sc(-60, 'discount');
    s.at(s.t + 900, 'stage_done', { ms: s.t + 900 - t0, skipped: false }, o, 'confirmation');
    s.t += 900;
    runSlow(s, o, 'receive', 'handoff');
    s.at(s.t, 'order_done', { clean: false, ms: 0, repeats: 0 }, o);
    s.counts.completed++;
    s.sc(40, 'order with repeats');
  };

  for (let i = 1; i <= night.orders; i++) {
    if (i > 1) s.gap(600);
    if (i === 2) typoOrder(i); else cleanOrder(i, true);
  }
  s.grade = s.counts.failed ? 'C' : 'B';

  const events = withScripts(base, 'orders', tiersOf(night), [s], night.orders);
  for (const e of events) {
    if (e.type === 'lane_ready' && e.lane === 1) e.detail = { tier: 'crew', label: CREW_LABEL, parts: [...parts] };
    if (e.type === 'chaos' && e.lane === 1 && e.detail!.creature === stormChaos.creature) e.detail = { ...e.detail, source: 'boss', deferred: true };
  }
  const ws = events.find((e) => e.type === 'wave_start')!;
  ws.detail = { ...ws.detail, seed: night.seed, pace: 'slow' };
  return finish(events, night.id, parts);
}

// ------------------------------------------------------------------------------------------------ public

/** One night's wave for any gear combination: `POST /api/wave/start {campaign}` in the mock plays this. */
export function campaignFixture(night: number, parts: readonly PartId[] = [], data = loadCampaign()): HauntEvent[] {
  const n = data.nights.find((x) => x.id === night);
  if (!n) throw new Error(`unknown night ${night}`);
  const ps = canonicalParts(parts);
  return n.finale ? finaleNight(n, ps) : plannedNight(n, ps);
}

/** The committed fixtures: no gear and the night's gear hint, for every night. */
export function campaignFixtureSpecs(data = loadCampaign()): { name: string; night: number; parts: PartId[] }[] {
  const out: { name: string; night: number; parts: PartId[] }[] = [];
  for (const n of data.nights) {
    out.push({ name: nightFixtureName(n.id), night: n.id, parts: [] });
    const hint = canonicalParts(n.gearHint);
    if (hint.length) out.push({ name: nightFixtureName(n.id, hint), night: n.id, parts: hint });
  }
  return out;
}

export const CAMPAIGN_FIXTURES: Record<string, () => HauntEvent[]> = Object.fromEntries(
  campaignFixtureSpecs().map((f) => [f.name, () => campaignFixture(f.night, f.parts)]),
);
